/* Splitter / linesiter state. Classes are declared `is native`
   with no user fields; the runtime supplies the real layout,
   stack-allocated value type (48 bytes). Both iterators share
   the same struct — linesiter leaves sep NULL. */
typedef struct {
    const char* src;
    uint64_t    src_len;
    const char* sep;
    uint64_t    sep_len;
    uint64_t    cursor;
    bool        done;
} z_t4391_t;

typedef z_t4391_t z_t4433_t;


static z_t4391_t z_t52_split(
    const z_t52_t* self, const z_t52_t* sep);
static z_t4391_t z_t52_split(
    const z_t52_t* self, const z_t52_t* sep) {
    z_t4391_t s;
    s.src = self->data;
    s.src_len = self->size;
    s.sep = sep->data;
    s.sep_len = sep->size;
    s.cursor = 0;
    s.done = (sep->size == 0);
    return s;
}


static z_t4396_t z_t4391_call(z_t4391_t* s);
